test('same-session restoration retains body/key; refreshed token, malformed and foreign records never reach GET or overwrite', async () => {
  const seed=harness({handler:c=>{if(c.method==='PUT')throw Error('unknown');return clone(actual.responses.linked_before.body);}});assert.equal(await seed.run(), false);
  const entry=[...seed.memory.entries()][0];
  function backing(memory){return{getItem:k=>memory.get(k)??null,setItem:(k,v)=>memory.set(k,v),compareAndRemoveItem:(k,raw)=>{if(memory.get(k)!==raw)return false;memory.delete(k);return true;}};}
  const memory=new Map([entry]),restored=harness({storage:backing(memory)});await restored.controller.reload();await restored.controller.reconcile();await restored.controller.retry();
  assert.deepEqual(restored.calls.find(c=>c.method==='PUT').body,seed.calls.find(c=>c.method==='PUT').body);assert.equal(memory.size,0);
  for(const mutation of ['token','json','actor','body','source']){let raw=entry[1];if(mutation==='json')raw='{malformed';else if(mutation!=='token'){const p=JSON.parse(raw);if(mutation==='actor')p.actor_ref='usr:foreign';if(mutation==='body')p.body.actor_ref='usr:foreign';if(mutation==='source')p.source_evidence.source_sha256='f'.repeat(64);raw=JSON.stringify(p);}
    const memory=new Map([[entry[0],raw]]),h=harness({storage:backing(memory)});if(mutation==='token')h.setToken('REFRESHED_TOKEN');
    await assert.rejects(h.controller.reload());assert.equal(h.calls.length,0);assert.equal(memory.get(entry[0]),raw);assert.equal(h.controller.isPending(),true);
  }
});
