for(const [name,capture] of [['move',actualMove],['duplicate',actualDuplicate]])test(`actual captured ${name} request and applied destination pass unmodified full DTO through mocked controller transport`,async()=>{
  const s=state('editor',capture);sourceLinkedRead(capture.responses.linked_before.body,s);sourceLinkedRead(capture.responses.linked_put.body,s);
  const h=harness({capture});assert.equal(await h.run(clone(capture.responses.linked_put.request.operations)),true);
  assert.deepEqual(h.calls.map(c=>c.method),['GET','PUT']);assert.deepEqual(h.calls[1].body,capture.responses.linked_put.request);
  assert.deepEqual(h.saved[0].receipt,capture.responses.linked_put.body.receipt);assert.deepEqual(h.saved[0].timeline,capture.responses.linked_put.body.timeline);
  assert.deepEqual(h.saved[0].parent_timeline,capture.responses.linked_before.body.timeline);
  const adjusted = name === 'move'; // Actual move 99 -> 12; actual duplicate requested 4 -> applied 4.
  assert.equal(h.saved[0].placement_adjusted,adjusted);assert.equal(h.saved[0].word_boundary_adjusted,false);assert.equal(h.memory.size,0);
  if(adjusted)assert.match(h.controller.getStatus(),/thứ tự cảnh/);else assert.doesNotMatch(h.controller.getStatus(),/thứ tự cảnh/);
  assert.doesNotMatch(h.controller.getStatus(),/giữ trọn từ/);
});
